test('community lists prefetch at login and render account-scoped cached rows while offline refresh waits',{timeout:40000},async()=>{
 const server=await serveBrowserFixture(path.resolve(__dirname,'..')),browser=await chromium.launch({headless:true,executablePath:executablePath(),args:['--no-sandbox']});const context=await browser.newContext({viewport:{width:390,height:740}});let hold=false,release=null,hubReads=0,groupReads=0;
 const friend={id:'edge',userId:'friend',nickname:'Ember cached',username:'ember',accepted:true},user={id:'cache-user',email:'cache@example.test',is_anonymous:false};
 try{
 await context.route('https://geurlwivdiqboylciqhl.supabase.co/**',accountSyncRoute(async route=>{const r=route.request(),body=r.postDataJSON()||{};let data={};
 if(r.url().includes('/auth/'))data=r.url().includes('/logout')?{}:r.url().includes('/user')?user:{user,access_token:'secret-access',refresh_token:'secret-refresh',expires_in:3600};
 else if(r.url().endsWith('/playroom_online')){if(body.p_action==='hub'){hubReads++;if(hold)await new Promise(resolve=>release=resolve);data={friends:[friend],conversations:[friend],invitations:[],rooms:[],password:'not-for-cache',messages:['private-body']};}else if(body.p_action==='group-list'){groupReads++;data={groups:[{id:'group',name:'Cached group',count:2}]};}else if(body.p_action==='unread')data={friends:[],groups:[],rooms:[]};else if(['inbox','group-inbox'].includes(body.p_action))data={cursor:'0',messages:[]};}
 else if(r.url().endsWith('/playroom_social'))data={profile:{nickname:'Тестовый игрок',username:'cache'},friends:[friend],rooms:[],invitations:[]};
 else if(r.url().endsWith('/playroom_cloud_saves_rpc'))data={saves:[],used:0};
 await route.fulfill({status:200,contentType:'application/json',body:JSON.stringify(data)});
 }));
 const page=await context.newPage();page.setDefaultTimeout(7000);await page.goto(server.url);await page.waitForFunction(()=>!!PlayroomAccountUI.service);assert.equal(hubReads,0);await page.evaluate(()=>PlayroomAccountUI.service.login('cache@example.test','password123'));await page.waitForFunction(()=>!!localStorage.getItem('playroom.community-cache.v1:cache-user'));assert(hubReads>0&&groupReads>0);const before=hubReads;
 await page.evaluate(()=>PlayroomCommunityUI.show());await page.locator('[data-community-chat=friend]').waitFor();assert.equal(hubReads,before,'fresh prefetch avoids another hub request on open');assert(await page.locator('[data-group-open=group]').isVisible());
 await page.evaluate(()=>PlayroomGroupUI.update([{id:'group',name:'Cached group',count:3}],{replace:true}));assert.match(await page.locator('[data-group-open=group]').innerText(),/· 3/);assert.equal(await page.evaluate(()=>JSON.parse(localStorage.getItem('playroom.community-cache.v1:cache-user')).groups[0].count),3,'metadata update is shared with account cache');
 await page.evaluate(()=>window.dispatchEvent(new CustomEvent('playroom:groups-updated',{detail:{accountId:'another-user',groups:[{id:'foreign',name:'Foreign group',count:9}]}})));assert.equal(await page.locator('[data-group-open=foreign]').count(),0,'other account metadata cannot populate the current list');assert.equal(hubReads,before,'metadata update needs no extra hub request');
 const cached=await page.evaluate(()=>localStorage.getItem('playroom.community-cache.v1:cache-user'));assert(!/secret|private-body|not-for-cache/.test(cached));
 hold=true;await page.reload();await page.waitForFunction(()=>PlayroomAccountUI.service?.snapshot().kind==='account');await page.evaluate(()=>PlayroomCommunityUI.show());await page.locator('[data-community-chat=friend]').waitFor();assert(await page.locator('[data-group-open=group]').isVisible(),'groups render from disk before hub returns');
 if(release){hold=false;release();release=null;}else hold=false;
 await page.evaluate(()=>PlayroomAccountUI.service.logout());await page.evaluate(()=>PlayroomCommunityUI.show());assert.equal(await page.locator('[data-community-chat=friend]').count(),0,'logout cannot show the previous account list');
 }finally{hold=false;release?.();await browser.close();await server.close();}
});

 test('chat navigation: nearest active invitations, bottom tracking and closed-chat anchors',{timeout:45000},async()=>{
 const server=await serveBrowserFixture(path.resolve(__dirname,'..')),browser=await chromium.launch({headless:true,executablePath:executablePath(),args:['--no-sandbox','--disable-background-networking']});const page=await browser.newPage({viewport:{width:390,height:740}});page.setDefaultTimeout(5000);const errors=[];page.on('pageerror',e=>errors.push(e.message));
 try{await page.goto(server.url);await page.waitForFunction(()=>PlayroomCommunityUI?.service);await page.evaluate(()=>{
  window.qaRows=Array.from({length:38},(_,i)=>({id:String(i+1),seq:i+1,body:'Сообщение '+(i+1)+' для проверки позиции чтения. '.repeat(3),at:new Date().toISOString(),mine:false,kind:[4,12,22,30].includes(i+1)?'invitation':'message',state:i===3?'expired':'active',inviteId:'invite-'+i,roomName:'Комната '+i}));
  PlayroomCommunityUI.service.call=async action=>action==='chat'?{messages:qaRows,through:'0'}:action==='hub'?{friends:[{userId:'peer',nickname:'Друг',accepted:true}],conversations:[]}:{};
  PlayroomChatState.merge('dm:peer',qaRows,{fetched:true});PlayroomChatUI.show({userId:'peer',nickname:'Друг',accepted:true});
 });const list=page.locator('[data-chat-messages]');await page.locator('.chat-message').last().waitFor();
 await list.evaluate(el=>{el.scrollTop=el.querySelector('[data-entity="message-18"]').offsetTop-el.offsetTop;PlayroomChatComponents.navigation(el);});
 await page.locator('[data-chat-scroll=up]:not([hidden])').waitFor();await page.locator('[data-chat-scroll=down]:not([hidden])').waitFor();
 await page.locator('[data-chat-scroll=up]').click();assert(await page.locator('[data-entity="message-12"]').evaluate(el=>{const a=el.getBoundingClientRect(),b=el.parentElement.getBoundingClientRect();return a.top>=b.top&&a.top<b.bottom;}));assert.equal(await page.locator('[data-chat-scroll=up]').isVisible(),false,'expired invitation does not produce a bubble');
 await page.locator('[data-chat-scroll=down]').click();assert(await page.locator('[data-entity="message-22"]').evaluate(el=>{const a=el.getBoundingClientRect(),b=el.parentElement.getBoundingClientRect();return a.top>=b.top&&a.top<b.bottom;}));
 await page.locator('[data-chat-scroll=down]').click();assert(await page.locator('[data-entity="message-30"]').evaluate(el=>{const a=el.getBoundingClientRect(),b=el.parentElement.getBoundingClientRect();return a.top>=b.top&&a.top<b.bottom;}));
 await list.evaluate(el=>{el.scrollTop=300;PlayroomChatComponents.navigation(el);});await list.evaluate(el=>{el.scrollTop+=80;});await page.locator('[data-chat-scroll=latest]:not([hidden])').waitFor();
 for(const width of [320,390,1280]){await page.setViewportSize({width,height:740});assert(await page.locator('.chat-scroll-zone').evaluate(el=>el.scrollWidth<=el.clientWidth+1));if(process.env.PLAYROOM_CAPTURE_DIR){require('node:fs').mkdirSync(process.env.PLAYROOM_CAPTURE_DIR,{recursive:true});await page.screenshot({path:path.join(process.env.PLAYROOM_CAPTURE_DIR,'chat-navigation-'+width+'.png')});}}
 await page.setViewportSize({width:390,height:740});const position=()=>list.evaluate(el=>{const box=el.getBoundingClientRect(),node=[...el.querySelectorAll('.chat-message')].find(n=>n.getBoundingClientRect().bottom>box.top);return{id:node.dataset.entity,offset:node.getBoundingClientRect().top-box.top};});
 const before=await position();await page.evaluate(()=>qaRows.push({...qaRows[0],id:'39',body:'Новое сообщение',kind:'message'}));await page.locator('[data-chat-refresh]').click();await page.locator('[data-entity="message-39"]').waitFor();let after=await position();assert.equal(after.id,before.id);assert(Math.abs(after.offset-before.offset)<3);
 await page.evaluate(()=>{PlayroomChatUI.close();qaRows.push({...qaRows[0],id:'40',body:'Пришло в закрытый чат',kind:'message'});PlayroomChatState.merge('dm:peer',qaRows,{fetched:true});PlayroomChatUI.show({userId:'peer',nickname:'Друг',accepted:true});});await page.locator('[data-entity="message-40"]').waitFor();after=await position();assert.equal(after.id,before.id);assert(Math.abs(after.offset-before.offset)<3,'closed chat keeps exact message offset');
 await page.locator('[data-chat-scroll=latest]').evaluate(el=>{el.hidden=false;});await page.locator('[data-chat-scroll=latest]').click();await page.evaluate(()=>qaRows.push({...qaRows[0],id:'41',body:'Следуем внизу',kind:'message'}));await page.locator('[data-chat-refresh]').click();await page.locator('[data-entity="message-41"]').waitFor();assert(await list.evaluate(el=>PlayroomChatState.near(el)));
 await page.evaluate(()=>{qaRows=qaRows.map(m=>({...m,seq:Number(m.id),shared:true}));PlayroomRoomChatUI.show({source:()=>({cloudGroup:true,roomId:'group',roomName:'Группа',game:{id:'group',name:'Группа'},connected:true,call:async()=>({messages:qaRows,team:null,older:false})})});});await page.locator('[data-room-chat-messages] .chat-message').last().waitFor();await page.locator('[data-room-chat-messages]').evaluate(el=>{el.scrollTop=400;PlayroomChatComponents.navigation(el);});await page.locator('[data-chat-scroll=down]:not([hidden])').waitFor();assert.equal(await page.locator('[data-room-chat-decline]').count(),0);assert.deepEqual(errors,[]);
 }finally{await browser.close();await server.close();}
 });

test('chat unread boundary is revealed on reopen without jumping away from older reading',{timeout:30000},async()=>{
 const server=await serveBrowserFixture(path.resolve(__dirname,'..')),browser=await chromium.launch({headless:true,executablePath:executablePath(),args:['--no-sandbox','--disable-background-networking']});const page=await browser.newPage({viewport:{width:390,height:740}});
 try{page.setDefaultTimeout(5000);await page.goto(server.url);await page.waitForFunction(()=>PlayroomCommunityUI?.service);
 for(const group of [false,true]){
  await page.evaluate(group=>{
   window.qaUnreadRows=Array.from({length:24},(_,i)=>({id:String(i+1),seq:i+1,body:'История переписки для проверки сохранения позиции чтения. '.repeat(3),at:new Date().toISOString(),mine:true,nickname:'Друг',kind:'message'}));
   const key=group?'group:unread-test':'dm:unread-test';window.qaUnreadKey=key;
   PlayroomCommunityUI.service.call=async action=>action==='chat'?{messages:qaUnreadRows,through:'24'}:action==='hub'?{friends:[{userId:'unread-test',nickname:'Друг',accepted:true}],conversations:[]}:{};
   window.qaUnreadShow=()=>group?PlayroomRoomChatUI.show({source:()=>({cloudGroup:true,roomId:'unread-test',roomName:'Группа',game:{id:'group',name:'Группа'},connected:true,call:async()=>({messages:qaUnreadRows,through:24,team:null,older:false})})}):PlayroomChatUI.show({userId:'unread-test',nickname:'Друг',accepted:true});
   window.qaUnreadClose=()=>group?PlayroomRoomChatUI.close():PlayroomChatUI.close();
   PlayroomChatState.merge(key,qaUnreadRows,{fetched:true});PlayroomChatState.get(key).through='24';qaUnreadShow();
  },group);
  const list=page.locator(group?'[data-room-chat-messages]':'[data-chat-messages]');await list.locator('.chat-message').last().waitFor();
  await list.evaluate(el=>{el.scrollTop=el.scrollHeight;window.qaUnreadTop=el.scrollTop;PlayroomChatState.remember(qaUnreadKey,el);});
  await page.evaluate(()=>{qaUnreadClose();qaUnreadRows.push({...qaUnreadRows[0],id:'25',seq:25,mine:false,body:'Непрочитанное сообщение'});PlayroomChatState.merge(qaUnreadKey,qaUnreadRows,{fetched:true});qaUnreadShow();});
  await list.locator('.chat-unread').waitFor();assert(await list.evaluate(el=>{const box=el.getBoundingClientRect(),r=el.querySelector('.chat-unread').getBoundingClientRect();return r.top>=box.top&&r.bottom<=box.bottom-6;}),'unread divider must be visible just below the previous reading position');
  const delta=await list.evaluate(el=>el.scrollTop-qaUnreadTop);assert(delta<150,'no jump to the end of unread messages');
  await list.evaluate(el=>{el.scrollTop=0;PlayroomChatState.remember(qaUnreadKey,el);});await page.evaluate(()=>{qaUnreadClose();qaUnreadRows.push({...qaUnreadRows[0],id:'26',seq:26,mine:false,body:'Ещё одно новое сообщение'});PlayroomChatState.merge(qaUnreadKey,qaUnreadRows,{fetched:true});qaUnreadShow();});await list.locator('.chat-unread').waitFor();assert(await list.evaluate(el=>el.scrollTop<3),'reading older history must remain at its original position');await page.evaluate(()=>qaUnreadClose());
 }
 }finally{await browser.close();await server.close();}
});

test('chat unread counters update before read acknowledgement and resist stale summaries',{timeout:30000},async()=>{
 const server=await serveBrowserFixture(path.resolve(__dirname,'..')),browser=await chromium.launch({headless:true,executablePath:executablePath(),args:['--no-sandbox','--disable-background-networking']}),page=await browser.newPage({viewport:{width:390,height:740}});page.setDefaultTimeout(5000);
 try{await page.goto(server.url);await page.waitForFunction(()=>PlayroomCommunityUI?.service);
 for(const group of [false,true]){
  await page.evaluate(group=>{
   window.qaCounterKey=group?'group:counter-test':'dm:counter-test';window.qaSeenStarted=false;window.qaSeenGate=new Promise(r=>window.qaSeenRelease=r);
   window.qaCounterRows=Array.from({length:33},(_,i)=>({id:String(i+1),seq:i+1,mine:i<30,body:'Сообщение '+(i+1),kind:'message',nickname:'Друг',at:new Date().toISOString()}));
   PlayroomCommunityUI.service.call=async(action,data)=>action==='chat'?{messages:qaCounterRows,through:'30'}:action==='read-messages'?(window.qaSeenStarted=true,qaSeenGate):action==='hub'?{friends:[{userId:'counter-test',nickname:'Друг',accepted:true}],conversations:[]}:{};
   PlayroomChatState.merge(qaCounterKey,qaCounterRows,{fetched:true});PlayroomChatState.summary([{key:qaCounterKey,through:'30',unread:3,invites:1}]);
   if(group)PlayroomRoomChatUI.show({source:()=>({cloudGroup:true,roomId:'counter-test',roomName:'Группа',game:{id:'group',name:'Группа'},connected:true,call:async c=>c.type==='room-chat-seen'?(window.qaSeenStarted=true,qaSeenGate):{messages:qaCounterRows,through:30,team:null,older:false}})});else void PlayroomChatUI.show({userId:'counter-test',nickname:'Друг',accepted:true});
  },group);
  await page.waitForFunction(()=>qaSeenStarted);assert.equal(await page.evaluate(()=>PlayroomChatState.count(qaCounterKey).unread),0,'visible messages clear before the server acknowledgement');
  await page.evaluate(()=>PlayroomChatState.summary([{key:qaCounterKey,through:'30',unread:3,invites:1}]));assert.equal(await page.evaluate(()=>PlayroomChatState.count(qaCounterKey).unread),0,'an in-flight old summary cannot resurrect a read badge');
  await page.evaluate(()=>{PlayroomChatState.merge(qaCounterKey,[{...qaCounterRows.at(-1),id:'34',seq:34,body:'Ещё не видно'}]);PlayroomChatState.summary([{key:qaCounterKey,through:'30',unread:4,invites:1}]);});assert.equal(await page.evaluate(()=>PlayroomChatState.count(qaCounterKey).unread),1,'a genuinely new unseen message remains counted');assert.equal(await page.evaluate(()=>PlayroomChatState.count(qaCounterKey).invites),1,'reading does not clear an active invitation');
  await page.evaluate(()=>{qaSeenRelease({});PlayroomChatState.summary([{key:qaCounterKey,through:'33',unread:1,invites:1}]);});assert.equal(await page.evaluate(()=>PlayroomChatState.count(qaCounterKey).unread),1);await page.evaluate(group=>group?PlayroomRoomChatUI.close():PlayroomChatUI.close(),group);
 }
 }finally{await page.evaluate(()=>window.qaSeenRelease?.({})).catch(()=>{});await browser.close();await server.close();}
});

test('invitation badges and cached join actions expire in background without reading chat',{timeout:30000},async()=>{
 const server=await serveBrowserFixture(path.resolve(__dirname,'..')),browser=await chromium.launch({headless:true,executablePath:executablePath(),args:['--no-sandbox','--disable-background-networking']}),page=await browser.newPage({viewport:{width:390,height:740}});
 try{await page.goto(server.url);await page.waitForFunction(()=>PlayroomCommunityUI?.service);
 await page.evaluate(()=>{
  window.qaInviteClosed=false;window.qaInviteReads=0;window.qaUnreadPolls=0;
  const keys=['dm:expiry-peer','group:expiry-group'];for(const key of keys)PlayroomChatState.merge(key,[{id:'20',seq:20,kind:'invitation',mine:false,state:'active',inviteId:'invite',body:'Комната',at:new Date().toISOString()}],{fetched:true});
  PlayroomChatNotifications.init({account:{snapshot:()=>({kind:'account',id:'expiry-user'}),subscribe:()=>{}},store:{read:()=>null,write:()=>{}},service:{call:async(action,data)=>{
   if(action==='unread'){qaUnreadPolls++;return {chats:keys.map(key=>({key,through:'0',unread:1,invites:qaInviteClosed?0:1}))};}
   if(['chat','group-read'].includes(action))return {messages:[{id:'20',seq:20,state:qaInviteClosed?'expired':'active'}]};
   if(['read-messages','group-seen'].includes(action))qaInviteReads++;
   return {cursor:'0',items:[]};
  }}});
 });await page.waitForFunction(()=>document.querySelector('#app .chat-counter-invitations'));
 await page.evaluate(async()=>{await PlayroomChatNotifications.poll();qaInviteClosed=true;await PlayroomChatNotifications.poll();});
 await page.waitForFunction(()=>!document.querySelector('#app .chat-counter-invitations'));assert.equal(await page.evaluate(()=>qaInviteReads),0,'expiration must not require reading a chat');
 assert.deepEqual(await page.evaluate(()=>['dm:expiry-peer','group:expiry-group'].map(k=>PlayroomChatState.get(k).rows[0].state)),['expired','expired']);assert.deepEqual(await page.evaluate(()=>['dm:expiry-peer','group:expiry-group'].map(k=>PlayroomChatState.count(k).unread)),[1,1],'unread messages remain separate from inactive invitations');
 const before=await page.evaluate(()=>qaUnreadPolls);await page.evaluate(()=>{dispatchEvent(new PageTransitionEvent('pagehide',{persisted:true}));dispatchEvent(new PageTransitionEvent('pageshow',{persisted:true}));});await page.waitForFunction(n=>qaUnreadPolls>n,before);
 assert.equal(await page.evaluate(()=>{PlayroomChatUI.show({userId:'expiry-peer',nickname:'Друг',accepted:true});return document.querySelectorAll('[data-chat-join]').length;}),0,'cached first paint cannot expose a stale join button');
 }finally{await browser.close();await server.close();}
});
